package com.rafi.daybook;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.util.*;
final class Reminders {
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("reminders",Context.MODE_PRIVATE);}
 static PendingIntent pending(Context c,int id,JSONObject r){Intent i=new Intent(c,ReminderReceiver.class).putExtra("number",id).putExtra("item",r.toString());return PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static synchronized void replace(Context c,String json){try{JSONArray list=new JSONArray(json);AlarmManager am=c.getSystemService(AlarmManager.class);JSONArray old=new JSONArray(prefs(c).getString("items","[]"));for(int i=0;i<old.length();i++)am.cancel(pending(c,i+1,old.getJSONObject(i)));prefs(c).edit().putString("items",json).apply();restore(c);}catch(JSONException ignored){}}
 static synchronized void restore(Context c){try{JSONArray list=new JSONArray(prefs(c).getString("items","[]"));Set<String> annual=new HashSet<>();for(int i=0;i<list.length();i++){JSONObject r=list.getJSONObject(i);if(r.has("annualMonth")){String key=r.getString("id").replaceFirst("-\\d{4}$","");if(!annual.add(key))continue;Calendar now=Calendar.getInstance(),next=Calendar.getInstance();next.clear();next.set(now.get(Calendar.YEAR),r.getInt("annualMonth")-1,r.getInt("annualDay"),0,0,0);if(next.getTimeInMillis()<=System.currentTimeMillis()){next.clear();next.set(now.get(Calendar.YEAR)+1,r.getInt("annualMonth")-1,r.getInt("annualDay"),0,0,0);}r.put("at",next.getTimeInMillis());}schedule(c,i+1,r);}}catch(JSONException ignored){}}
 static void schedule(Context c,int id,JSONObject r){long at=r.optLong("at");if(at<=System.currentTimeMillis())return;AlarmManager am=c.getSystemService(AlarmManager.class);PendingIntent pi=pending(c,id,r);try{if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);}}
}
